package org.sleepwell.app;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public final class AlarmDefaultsStorageTest {
    final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();interface Task{void run(SharedPreferences prefs)throws Exception;}
    void fixture(Task task)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());String name="alarm-defaults-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(name,0);try{task.run(prefs);}finally{try{assertTrue(prefs.edit().clear().commit());}finally{assertTrue(c.deleteSharedPreferences(name));assertEquals(before,Prefs.of(c).getAll());}}}
    @Test public void privateDefaultsRoundTripAreIndependentAndResetRestoresLegacyFactory()throws Exception{fixture(prefs->{assertNull(AlarmDefaultsSettings.read(prefs).defaults);assertEquals(85,AlarmDefaultsSettings.read(prefs).create(1).volume);Alarm source=new Alarm(77);source.enabled=true;source.volume=38;source.hour=23;source.days.add(4);source.tone="content://fixture/alarm";source.toneDisplayName="Original recording";source.setRoutine(new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Walk",1,30))));String sourceJson=source.json().toString();AlarmDefaultsSettings.Port port=AlarmDefaultsSettings.of(prefs);port.save(new AlarmDefaults(source));Alarm result=port.read().create(9);assertEquals(38,result.volume);assertEquals(30,result.challenges().tasks.get(0).targetSteps);assertEquals(source.tone,result.tone);assertEquals(source.toneDisplayName,result.toneDisplayName);assertEquals(7,result.hour);assertFalse(result.enabled);assertTrue(result.days.isEmpty());assertEquals(sourceJson,source.json().toString());port.save(null);assertTrue(prefs.getAll().isEmpty());assertEquals(85,port.read().create(10).volume);});}
    @Test public void malformedOrAuthorityBearingTemplatesFailClosedWithoutChangingSavedBytes()throws Exception{fixture(prefs->{JSONObject good=new JSONObject(AlarmDefaultsJson.encode(new AlarmDefaults(new Alarm(1))));for(Object bad:new Object[]{"85",true,JSONObject.NULL,85.5,101,Double.MAX_VALUE}){JSONObject root=new JSONObject(good.toString());root.getJSONObject("settings").put("volume",bad);assertThrows(IllegalArgumentException.class,()->AlarmDefaultsJson.decode(root.toString()));}for(String key:new String[]{"enabled","id","days","skip","nap","scheduleError"}){JSONObject root=new JSONObject(good.toString());root.getJSONObject("settings").put(key,1);assertThrows(IllegalArgumentException.class,()->AlarmDefaultsJson.decode(root.toString()));}JSONObject missing=new JSONObject(good.toString());missing.getJSONObject("settings").remove("snoozeLimit");assertThrows(IllegalArgumentException.class,()->AlarmDefaultsJson.decode(missing.toString()));assertTrue(prefs.edit().putString(AlarmDefaultsSettings.KEY,missing.toString()).commit());Map<String,?> before=new HashMap<>(prefs.getAll());assertFalse(AlarmDefaultsSettings.read(prefs).error.isEmpty());assertEquals(85,AlarmDefaultsSettings.read(prefs).create(2).volume);assertEquals(before,prefs.getAll());});}
    @Test public void templatesRetainTheirImportedToneGrantAndNeverEnterPortableAlarmRows()throws Exception{fixture(prefs->{AlarmDefaultsSettings.Factory old=AlarmDefaultsSettings.factory;String database="alarm-template-"+UUID.randomUUID()+".db";try(Store store=new Store(c,database)){Alarm existing=new Alarm(3);existing.volume=72;store.save(existing);String before=store.backup().toString();Alarm source=new Alarm(1);source.tone="content://fixture/shared";AlarmDefaultsSettings.of(prefs).save(new AlarmDefaults(source));AlarmDefaultsSettings.factory=context->AlarmDefaultsSettings.of(prefs);assertTrue(AlarmDefaultsSettings.references(c,source.tone));assertFalse(AlarmDefaultsSettings.references(c,"content://fixture/other"));assertEquals(before,store.backup().toString());assertEquals(72,store.alarm(3).volume);AlarmDefaultsSettings.of(prefs).save(null);assertFalse(AlarmDefaultsSettings.references(c,source.tone));}finally{AlarmDefaultsSettings.factory=old;assertTrue(c.deleteDatabase(database));}});}
}
